151	     * Handles exception thrown by Bean Validation on controller methods parameters
152	     *
153	     * @param e The {@link MethodArgumentNotValidException} to be handled
154	     * @param request {@link HttpServletRequest} object referring to the current request.
155	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
156	     */
157	    @ExceptionHandler(MethodArgumentNotValidException.class)
158	    @ResponseBody
159	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
160	        HttpStatus status = HttpStatus.BAD_REQUEST;
161	        BindingErrorsResponse errors = new BindingErrorsResponse();
162	        BindingResult bindingResult = e.getBindingResult();
163	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
164	        if (bindingResult.hasErrors()) {
165	            errors.addAllErrors(bindingResult);
166	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
167	                .map(FieldError::getField)
168	                .distinct()
169	                .toList();
170	            detail.setProperty("errors", invalidFields);
171	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
172	                .map(fieldError -> {
173	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
174	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
175	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
176	                        fieldError.getField(),
177	                        defaultMessage,
178	                        rejectedValue);
179	                    return new ValidationMessageDto(message)
180	                        .putAdditionalProperty("field", fieldError.getField())
181	                        .putAdditionalProperty("rejectedValue", rejectedValue)
182	                        .putAdditionalProperty("defaultMessage", defaultMessage);
183	                })
184	                .toList();
185	            logger.debug("Validation error at {} {}: {}",
186	                request.getMethod(),
187	                request.getRequestURI(),
188	                bindingResult.getFieldErrors());
189	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
190	            return ResponseEntity.status(status).body(detail);
191	        }
192	        return ResponseEntity.status(status).body(detail);
193	    }
